import { NextResponse } from 'next/server'
import { PrismaClient } from '../../../../lib/generated/client'
import { TreeNode } from '@/lib/types'

const prisma = new PrismaClient()

export async function GET() {
  try {
    const nodes = await (prisma as any).libraryNode.findMany({
      orderBy: { order: 'asc' }
    })

    const nodesMap: Record<string, any> = {}
    nodes.forEach(n => {
      nodesMap[n.id] = {
        id: n.id,
        name: n.name,
        sanskrit: n.sanskrit || undefined,
        verseCount: n.verseCount || undefined,
        type: n.type as any,
        meta: (n.meta as any) || undefined,
        children: []
      }
    })

    const tree: TreeNode[] = []
    nodes.forEach(n => {
      if (n.parentId && nodesMap[n.parentId]) {
        nodesMap[n.parentId].children.push(nodesMap[n.id])
      } else {
        tree.push(nodesMap[n.id])
      }
    })
    return NextResponse.json(tree)
  } catch (error: any) {
    console.error('Error fetching library tree:', error)
    return NextResponse.json({ error: error.message || 'Internal Server Error' }, { status: 500 })
  }
}

